def successorParent : F.SuccessorIndices G → Option (F.SuccessorIndices G)
  | .inl i => (F.parent i).map Sum.inl
  | .inr (i, j) => (G.parent j).map (fun a =>
      if h : a = G.index then Sum.inl i else Sum.inr (i, ⟨a, h⟩))

